<?php
namespace App\Http\Controllers;
use App\Models\{ActivityLog,Client,Company,DataRecoveryCase,Device,HomeServicePreorder,RepairOrder,User};
use App\Mail\{DataRecoveryReceived,RepairOrderReceived};
use App\Rules\ValidRut;
use App\Services\{HomeServicePhotoService,TransportQuoteService};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Mail,Storage};
use Illuminate\Validation\Rule;
use RuntimeException;
class HomeServicePreorderController extends Controller {
 private function area(Request $r):string{$area=$r->query('area','servicio_tecnico');abort_unless(in_array($area,['servicio_tecnico','recuperadata'],true),404);return $area;}
 public function mobileApp(Request $r){$area=$this->area($r);$items=HomeServicePreorder::with(['client','assignedUser'])->when($r->user()->role!=='super_admin',fn($q)=>$q->where('company_id',$r->user()->company_id))->where('service_area',$area)->whereNull('completed_at')->orderByRaw('scheduled_at IS NULL')->orderBy('scheduled_at')->latest('id')->get();return view('home-service.mobile-index',['preorders'=>$items,'area'=>$area]);}
 public function index(Request $r){$area=$this->area($r);$items=HomeServicePreorder::with(['client','assignedUser','repairOrder','dataRecoveryCase'])->when($r->user()->role!=='super_admin',fn($q)=>$q->where('company_id',$r->user()->company_id))->where('service_area',$area)->when($r->filled('status'),fn($q)=>$q->where('status',$r->status))->when($r->filled('q'),function($q)use($r){$term='%'.mb_strtolower($r->q).'%';$q->where(fn($q)=>$q->whereRaw('LOWER(code) LIKE ?',[$term])->orWhereRaw('LOWER(external_quote_code) LIKE ?',[$term])->orWhereHas('client',fn($q)=>$q->whereRaw('LOWER(name) LIKE ?',[$term])));})->latest()->paginate(50)->withQueryString();return view('home-service.index',['preorders'=>$items,'statuses'=>HomeServicePreorder::STATUSES,'area'=>$area]);}
 public function create(Request $r){$area=$this->area($r);return view('home-service.create',['companies'=>$this->companies($r),'users'=>$this->users($r),'area'=>$area]);}
 public function lookup(Request $r,TransportQuoteService $service){$data=$r->validate(['company_id'=>['required','exists:companies,id'],'code'=>['required','string','max:32']]);$company=$this->company($r,(int)$data['company_id']);try{$quote=$service->find($company,$data['code']);if(($quote['status']??'')==='expired')return response()->json(['message'=>'La estimación está vencida.'],422);return response()->json($quote);}catch(\Throwable $e){return response()->json(['message'=>$e->getMessage()],422);}}
 public function store(Request $r,TransportQuoteService $service){$data=$this->validateStore($r);$company=$this->company($r,(int)$data['company_id']);$quote=$service->find($company,$data['external_quote_code']);if(($quote['status']??'')==='imported')throw \Illuminate\Validation\ValidationException::withMessages(['external_quote_code'=>'Esta estimación ya fue importada en '.$quote['preorder_code'].'.']);if(($quote['status']??'')==='expired')throw \Illuminate\Validation\ValidationException::withMessages(['external_quote_code'=>'La estimación se encuentra vencida.']);$preorder=DB::transaction(function()use($r,$data,$company,$quote,$service){Company::whereKey($company->id)->lockForUpdate()->firstOrFail();$client=$this->resolveClient($data,$company->id);$last=HomeServicePreorder::where('company_id',$company->id)->max('code');$code='PRE-'.str_pad((string)(((int)substr((string)$last,4))+1),6,'0',STR_PAD_LEFT);$p=HomeServicePreorder::create(['company_id'=>$company->id,'client_id'=>$client->id,'assigned_user_id'=>$data['assigned_user_id']??null,'code'=>$code,'external_quote_code'=>strtoupper($quote['code']),'service_area'=>$data['service_area'],'status'=>!empty($data['scheduled_at'])?'agendada':'aceptada','address'=>$quote['address'],'latitude'=>$quote['latitude']??null,'longitude'=>$quote['longitude']??null,'distance_km'=>$quote['distance_km'],'pickup_amount'=>$quote['pickup_amount'],'delivery_amount'=>$quote['delivery_amount'],'transport_total'=>$quote['total_amount'],'external_snapshot'=>$quote,'conversation_summary'=>$data['conversation_summary'],'prediagnosis'=>$data['prediagnosis'],'reported_problem'=>$data['reported_problem'],'scheduled_at'=>$data['scheduled_at']??null,'time_window'=>$data['time_window']??null,'unit_type'=>$data['unit_type']??null]);$service->claim($company,$quote['code'],$code);return $p;});ActivityLog::record($r,'home_preorder_created','Preorden creada: '.$preorder->code,$preorder,$preorder->company_id);return redirect()->route('home-service.show',$preorder)->with('success','Preorden creada y estimación vinculada.');}
 public function show(HomeServicePreorder $homeService){$this->authorize($homeService);return view('home-service.show',['preorder'=>$homeService->load(['company','client','assignedUser','photos','repairOrder','dataRecoveryCase'])]);}
 public function edit(HomeServicePreorder $homeService){$this->authorize($homeService);return view('home-service.edit',['preorder'=>$homeService->load('client'),'users'=>$this->users(request()),'statuses'=>HomeServicePreorder::STATUSES]);}
 public function update(Request $r,HomeServicePreorder $homeService){$this->authorize($homeService);$data=$r->validate(['assigned_user_id'=>['nullable','exists:users,id'],'status'=>['required',Rule::in(array_keys(HomeServicePreorder::STATUSES))],'scheduled_at'=>['nullable','date'],'time_window'=>['nullable','string','max:100'],'conversation_summary'=>['nullable','string'],'prediagnosis'=>['nullable','string'],'reported_problem'=>['nullable','string']]);$homeService->update($data);ActivityLog::record($r,'home_preorder_updated','Preorden actualizada: '.$homeService->code,$homeService,$homeService->company_id);return redirect()->route('home-service.show',$homeService)->with('success','Preorden actualizada.');}
 public function destroy(Request $r,HomeServicePreorder $homeService){$this->authorize($homeService);$code=$homeService->code;$companyId=$homeService->company_id;$area=$homeService->service_area;$hasGeneratedTarget=$homeService->repair_order_id||$homeService->data_recovery_case_id;DB::transaction(fn()=>$homeService->delete());if(!$hasGeneratedTarget)Storage::disk('local')->deleteDirectory('home-service/'.$homeService->id);elseif($homeService->signature_path)Storage::disk('local')->delete($homeService->signature_path);ActivityLog::record($r,'home_preorder_deleted','Preorden eliminada: '.$code,null,$companyId);return redirect()->route('home-service.index',['area'=>$area])->with('success','Retiro eliminado correctamente.');}
 public function mobile(HomeServicePreorder $homeService){$this->authorize($homeService);return view('home-service.mobile',['preorder'=>$homeService->load(['client','company','photos'])]);}
 public function finalize(Request $r,HomeServicePreorder $homeService,HomeServicePhotoService $photos){$this->authorize($homeService);abort_if($homeService->completed_at,422,'La preorden ya fue finalizada.');$data=$r->validate(['unit_type'=>['required','string','max:100'],'brand'=>['nullable','string','max:100'],'model'=>['nullable','string','max:100'],'capacity'=>['nullable','string','max:50'],'serial_number'=>['nullable','string','max:150'],'interface'=>['nullable','string','max:100'],'accessories'=>['nullable','string'],'physical_condition'=>['nullable','string'],'delivered_by_other'=>['nullable','boolean'],'signer_name'=>['nullable','required_if:delivered_by_other,1','string','max:255'],'signer_rut'=>['nullable','required_if:delivered_by_other,1',new ValidRut],'signature'=>['required','string'],'photos'=>['required','array','min:1','max:5'],'photos.*'=>['image','max:10240'],'label_photo_index'=>['nullable','integer','min:0','max:4']]);if(!$r->boolean('delivered_by_other')){$data['signer_name']=$homeService->client->name;$data['signer_rut']=$homeService->client->formatted_rut?:$homeService->client->rut;}foreach($r->file('photos') as $i=>$photo)$photos->store($homeService,$photo,(int)($data['label_photo_index']??-1)===$i);$signature=$this->storeSignature($homeService,$data['signature']);$homeService->update(collect($data)->only(['unit_type','brand','model','capacity','serial_number','interface','accessories','physical_condition','signer_name','signer_rut'])->all()+['signature_path'=>$signature,'signed_at'=>now()]);$target=DB::transaction(fn()=> $this->convert($homeService->fresh(['client','photos'])));try{$this->sendCompletionEmail($target);}catch(\Throwable $e){report($e);$target->update(['email_status'=>'error','email_error'=>mb_substr($e->getMessage(),0,1000)]);}ActivityLog::record($r,'home_preorder_finalized','Preorden finalizada: '.$homeService->code,$homeService,$homeService->company_id);$created=$target instanceof RepairOrder?'orden '.$target->code:'caso '.$target->code;return redirect()->route('home-service.mobile-app')->with('success','Retiro finalizado y '.$created.' creado correctamente.');}
 private function convert(HomeServicePreorder $p){Company::whereKey($p->company_id)->lockForUpdate()->firstOrFail();$gross=(float)$p->transport_total;$net=round($gross/1.19);$tax=$gross-$net;if($p->service_area==='recuperadata'){$last=DataRecoveryCase::where('company_id',$p->company_id)->max('code');$case=DataRecoveryCase::create(['company_id'=>$p->company_id,'client_id'=>$p->client_id,'received_by'=>$p->assigned_user_id,'code'=>'RD-'.str_pad((string)(((int)substr((string)$last,3))+1),6,'0',STR_PAD_LEFT),'status'=>'recibido','unit_type'=>$p->unit_type,'brand'=>$p->brand,'model'=>$p->model,'capacity'=>$p->capacity,'serial_number'=>$p->serial_number,'interface'=>$p->interface,'accessories'=>$p->accessories,'observations'=>$p->physical_condition,"net_amount"=>$net,"tax_amount"=>$tax,"total_amount"=>$gross,'received_at'=>now()]);foreach($p->photos as $photo)$case->photos()->create(collect($photo->toArray())->only(['path','original_name','width','height','size'])->all());$case->statusLogs()->create(['user_id'=>auth()->id(),'status'=>'recibido','comment'=>'Creado desde retiro '.$p->code]);$p->update(['data_recovery_case_id'=>$case->id,'status'=>'finalizada','completed_at'=>now()]);return $case;}$device=Device::create(['company_id'=>$p->company_id,'client_id'=>$p->client_id,'type'=>$p->unit_type,'brand'=>$p->brand,'model'=>$p->model,'serial_number'=>$p->serial_number,'accessories'=>$p->accessories,'physical_condition'=>$p->physical_condition]);$last=RepairOrder::where('company_id',$p->company_id)->max('code');$order=RepairOrder::create(['company_id'=>$p->company_id,'client_id'=>$p->client_id,'device_id'=>$device->id,'code'=>'OT-'.str_pad((string)(((int)substr((string)$last,3))+1),6,'0',STR_PAD_LEFT),'status'=>'ingresado','service_mode'=>'diagnostico','reported_problem'=>$p->reported_problem?:'Retiro a domicilio','initial_observations'=>$p->prediagnosis,'labor_amount'=>$net,'net_amount'=>$net,'tax_amount'=>$tax,'total_amount'=>$gross]);$order->devices()->sync([$device->id]);$order->statusLogs()->create(['status'=>'ingresado','comment'=>'Creada desde retiro '.$p->code]);foreach([['Retiro a domicilio',(float)$p->pickup_amount],['Entrega a domicilio',(float)$p->delivery_amount]] as [$description,$amount]){$itemNet=round($amount/1.19);$order->items()->create(['description'=>$description,'quantity'=>1,'unit_price'=>$itemNet,'total'=>$itemNet]);}foreach($p->photos as $photo)$order->photos()->create(['device_id'=>$device->id]+collect($photo->toArray())->only(['path','original_name','category','width','height','size'])->all());$p->update(['repair_order_id'=>$order->id,'status'=>'finalizada','completed_at'=>now()]);return $order;}
 private function storeSignature(HomeServicePreorder $p,string $data):string{if(!preg_match('/^data:image\/png;base64,(.+)$/',$data,$m))throw \Illuminate\Validation\ValidationException::withMessages(['signature'=>'La firma no es válida.']);$raw=base64_decode($m[1],true);if($raw===false||strlen($raw)>2_000_000)throw \Illuminate\Validation\ValidationException::withMessages(['signature'=>'La firma no es válida o es demasiado grande.']);$source=@imagecreatefromstring($raw);if(!$source)throw \Illuminate\Validation\ValidationException::withMessages(['signature'=>'No fue posible procesar la firma.']);ob_start();imagewebp($source,null,85);$webp=ob_get_clean();imagedestroy($source);$path='home-service/'.$p->id.'/firma.webp';Storage::disk('local')->put($path,$webp);return $path;}
 private function sendCompletionEmail(RepairOrder|DataRecoveryCase $target):void{$target->load(['company','client','photos','homeServicePreorder']);if(!$target->client->email){$target->update(['email_status'=>'omitido','email_error'=>'El cliente no tiene correo registrado.']);return;}$c=$target->company;if(!$c->smtp_host||!$c->smtp_username||!$c->smtp_password)throw new RuntimeException('La empresa no tiene completa su configuración SMTP.');config(['mail.mailers.company_smtp'=>['transport'=>'smtp','scheme'=>$c->smtp_security==='ssl'?'smtps':null,'host'=>$c->smtp_host,'port'=>$c->smtp_port?:587,'username'=>$c->smtp_username,'password'=>$c->smtp_password,'timeout'=>30,'auto_tls'=>$c->smtp_security!=='none','local_domain'=>parse_url((string)config('app.url'),PHP_URL_HOST)]]);$mail=$target instanceof RepairOrder?new RepairOrderReceived($target->load(['devices','items'])):new DataRecoveryReceived($target);Mail::mailer('company_smtp')->to($target->client->email)->send($mail);$target->update(['email_status'=>'enviado','emailed_at'=>now(),'email_error'=>null]);}
 private function validateStore(Request $r):array{if($r->filled('client_rut'))$r->merge(['client_rut'=>ValidRut::format($r->client_rut)]);return $r->validate(['company_id'=>['required','exists:companies,id'],'external_quote_code'=>['required','string','max:32'],'client_rut'=>['required',new ValidRut],'client_name'=>['required','string','max:255'],'client_email'=>['nullable','email'],'client_phone'=>['required','string','max:50'],'client_address'=>['nullable','string','max:255'],'service_area'=>['required','in:servicio_tecnico,recuperadata'],'assigned_user_id'=>['nullable','exists:users,id'],'conversation_summary'=>['required','string'],'prediagnosis'=>['required','string'],'reported_problem'=>['required','string'],'scheduled_at'=>['nullable','date'],'time_window'=>['nullable','string','max:100'],'unit_type'=>['nullable','string','max:100']]);}
 private function resolveClient(array $d,int $company):Client{$client=Client::where('company_id',$company)->whereRaw("replace(replace(replace(upper(rut),'.',''),'-',''),' ','') = ?",[ValidRut::clean($d['client_rut'])])->first();$values=['name'=>$d['client_name'],'email'=>$d['client_email']??null,'phone'=>$d['client_phone'],'address'=>$d['client_address']??$d['address']??null];if($client){$client->update($values);return $client;}return Client::create($values+['company_id'=>$company,'rut'=>$d['client_rut']]);}
 private function companies(Request $r){return Company::query()->when($r->user()->role!=='super_admin',fn($q)=>$q->whereKey($r->user()->company_id))->orderBy('name')->get();} private function users(Request $r){return User::query()->when($r->user()->role!=='super_admin',fn($q)=>$q->where('company_id',$r->user()->company_id))->where('is_active',true)->orderBy('name')->get();} private function company(Request $r,int $id):Company{$company=Company::findOrFail($r->user()->role==='super_admin'?$id:$r->user()->company_id);return $company;} private function authorize(HomeServicePreorder $p):void{abort_if(request()->user()->role!=='super_admin'&&$p->company_id!==request()->user()->company_id,403);}
}
